                Story("hy-travel-03", Lang.Hy, StoryTheme.Travel,
                    "Սենյակակիցը",
                    "Տասներկու ժամ ճանապարհից հետո {@1ը} հասնում է հյուրանոց, իսկ միակ մահճակալին քնած է մի {կենդանի#1}։ Ադմինիստրատորը ստուգում է համակարգիչը. սենյակն ամրագրել է {#1}-ը դեռ 2019 թվականին և վճարել է {ուտելիք}-ով։ {@1ը} առաջարկում է կիսել մահճակալը, բայց այնտեղ արդեն ցուցանակ է կախված՝ «{ցանկացած բառ}»։ Այնպես որ {@1ը} քնում է լոգարանում, իսկ բարձի փոխարեն՝ {առարկա}։ Առավոտյան {#1}-ը նախաճաշ է ստանում անկողնում, իսկ {@1ը}՝ հաշիվ լոգարանի համար։ {#1}-ը կարծիք է թողնում՝ հինգ աստղ, {ածական} սենյակ, բայց լոգարանի հյուրը շատ աղմկոտ է։"),
                Story("hy-travel-04", Lang.Hy, StoryTheme.Travel,
                    "Հանելուկներով նավիգատորը",
                    "{@1ը} մեքենա է վարձում, բայց նրա նավիգատորը խոսում է միայն հանելուկներով։ «Թեքվիր այնտեղ, որտեղ {կենդանի}-ն ստվեր չունի», – ասում է նա, և {@1ը} մի ժամ թեքվում է ամեն ագարակի մոտ։ «Կանգնիր այնտեղ, որտեղ քնած է {առարկա}-ն», – և {@1ը} կանգնում է կահույքի խանութի առաջ։ Վերջապես {@2ը} մեկը գուշակում է. պատասխանը «{ցանկացած բառ#1}» է, և այն տանում է {վայր}-ի մոտ։ Այնտեղ փուչիկներ են, {ուտելիք}-ից պատրաստված տորթ և «{#1}» գրությամբ պաստառ։ Նավիգատորի ծննդյան օրն է, և նա այս երթուղին պլանավորել է {թիվ} տարի։ {@1ը} մնում է տորթ ուտելու, և նավիգատորը վերջապես պարզ է խոսում. «Ձախ։ Եվ հաջորդ անգամ նվերով՝ {առարկա}»։"),
                Story("hy-travel-05", Lang.Hy, StoryTheme.Travel,
                    "Վրանն իր կարծիքն ունի",
                    "{@1ը} {վայր}-ում մի հանգիստ գիշեր է ուզում անցկացնել լճի ափին, բայց նոր վրանն իր կարծիքն ունի։ Հարթ մարգագետինը չի հարմարում, որովհետև խոտից {ուտելիք}-ի հոտ է գալիս։ Անտառն էլ չի հարմարում. այնտեղից վրանին ծուռ է նայում մի {կենդանի}։ {@1ը} վրանը քարշ է տալիս բլրի վրա, և վրանը համաձայնում է մեկ պայմանով՝ բարձը պետք է {առարկա#1}-ի տեսք ունենա։ Կեսգիշերին վրանը ներս է թողնում ևս երեք վրան՝ հիանալու {ածական} տեսարանով։ Առավոտյան {@1ը} քնած է դրսում, իսկ վրանները հերթով գրկում են {#1}-ը։"),
                Story("hy-travel-06", Lang.Hy, StoryTheme.Travel,
                    "Փոքրիկ կրուիզը",
                    "{@1ը} շքեղ կրուիզ է գնում՝ հարյուր զվարճանքով, բայց նավը թիավարող նավակ է դուրս գալիս։ Նավապետը տալիս է թիակները և ցուցակը՝ զվարճանք առաջին՝ թիավարել, երկրորդ՝ {գործողություն, օրինակ՝ պարել}։ Ամբողջ օրը նրանց հետևից լողում է հսկա լայներ, և ուղևորները դրոշներ են թափահարում ու գոռում՝ «{ցանկացած բառ}»։ Մայրամուտին լայների նավապետը հայտարարում է. իրենց մոտ վերջացել է {ուտելիք#1}-ը, իսկ վերջին տուփը նավակում է։ {@1ը} տուփը փոխում է ամբողջ լայների հետ, բանալիներով հանդերձ։ Հիմա {@1ը} լայներով լողում է {վայր}-ի կողմը, իսկ հին նավապետը թիավարում է հետևից՝ {առարկա}-ով և վերջին {#1}-ով։"),
                Story("hy-love-01", Lang.Hy, StoryTheme.Love,
                    "Սեղան չորսի համար",
                    "{@1ը} կատարյալ առաջին ժամադրություն է ուզում և սեղան է պատվիրում «{ցանկացած բառ#1}» ռեստորանում։ Բայց կողքի սեղանի մոտ, ճաշացանկի հետևում, արդեն թաքնված է ժամադրության մյուս կողմի մայրը և {ուտելիք} է վայելում։ {@1ը} նայում է սեղանի տակ. այնտեղ նստած է իր սեփական մայրը՝ ձեռքին մի {առարկա}՝ ամեն դեպքի համար։ Մայրերը նկատում են իրար և բարձրաձայն գնահատականներ են տալիս, ինչպես ժյուրին {կենդանի}-ի ցուցահանդեսում։ Աղանդերի ժամին մայրերն արդեն համարներ են փոխանակել և միասին {վայր}-ում հանգստանալու ծրագիր են կազմում։ Հիմա մայրերն ամեն ուրբաթ ընթրում են «{#1}»-ում, իսկ {@1ը} և մյուսը հրավեր չեն ստանում։"),
                Story("hy-love-02", Lang.Hy, StoryTheme.Love,
                    "Աղավնու փորձությունը",
                    "{@1ը} {վայր}-ում ծնկի է իջնում ամուսնության առաջարկ անելու, բայց աղավնին գողանում է մատանին ու թռչում։ Երկրորդ անգամ մատանին թաքցված է {ուտելիք#1}-ի մեջ, բայց աղավնին կուլ է տալիս ամբողջ {#1}-ը։ Երրորդ անգամ {@1ը} վահանի պես բռնում է մի {առարկա}, բայց աղավնին վերադառնում է օգնականով՝ {կենդանի}։ Հանկարծ նստարանին նստած տատիկը սուլում է, և երկու թռչունն էլ իջնում են նրա գլխարկին։ Պարզվում է՝ տատիկն աղավնիներին սովորեցնում է ստուգել այստեղ արվող ամեն առաջարկ, և {@1ը} անցնում է ստուգումը՝ «{ցանկացած բառ}»։ Հարսանիքին աղավնին մատանիները բերում է նորից {#1}-ի մեջ և ժամանակին է հասնում։"),
                Story("hy-love-03", Lang.Hy, StoryTheme.Love,
                    "Մեթչ",
                    "Ծանոթությունների հավելվածը {@1ին} զույգ է գտնում՝ {վայր}-ում կանգնած վաճառքի ավտոմատ։ Ավտոմատի պրոֆիլում գրված է՝ սիրում է {ուտելիք#1}, ատում է մանրադրամ, փնտրում է ինչ-որ {ածական} բան։ Առաջին ժամադրությանը {@1ը} ծաղիկներ է բերում, իսկ ավտոմատը պատասխան նվեր է տալիս՝ {#1} և պլաստիկե {կենդանի}։ Ժամադրությունը լավ է անցնում, {@1ը} մոտենում է, և ավտոմատը պահակ է կանչում։ Պահակը գալիս է, տեսնում ավտոմատը և հոգոց հանում՝ «{ցանկացած բառ}, էլի դու»։ Պահակը ավտոմատի նախկինն է, և հիմա {@1ը} ամեն առավոտ {#1} է գնում՝ միայն պահակին խանդեցնելու համար։"),
                Story("hy-love-04", Lang.Hy, StoryTheme.Love,
                    "Բնակարան 14",
                    "{@1ը} սիրային նամակ է գրում 41-րդ բնակարանում ապրողին, բայց նամակը սխալմամբ հասնում է 14-րդ բնակարան։ Պատասխանը գալիս է հաջորդ օրը մի տատիկից, և նամակում {ուտելիք#1}-ի բաղադրատոմս է։ {@1ը} գրում է՝ բացատրելու, իսկ տատիկը չորս էջ է գրում իր {կենդանի}-ի մասին։ Երեք ամիս նրանք նամակագրվում են ամեն երեքշաբթի՝ եղանակի, {վայր}-ի և ամենակարևորի՝ {#1}-ի մասին։ Հետո դուռը թակում է 41-րդ բնակարանի բնակիչը՝ ձեռքին {առարկա}. տատիկը նրա բարեկամն է և ամեն ինչ պատմել է։ Հիմա {@1ը} և 41-րդ բնակարանի բնակիչը զույգ են, բայց ամեն երեքշաբթի {@1ը} դեռ նամակ է գրում 14-րդ բնակարան և ստորագրում՝ «{ցանկացած բառ}»։"),
                Story("hy-love-05", Lang.Hy, StoryTheme.Love,
                    "Վեճերի կակտուսը",
                    "Տարեդարձի առթիվ {@1ը} {@2ին} կակտուս է նվիրում, որը մեծանում է ամեն անգամ, երբ նրանք վիճում են։ Առաջին երեկոյան նրանք վիճում են {ուտելիք}-ի պատճառով, և առավոտյան կակտուսն արդեն {առարկա}-ից բարձր է։ {@1ը} առաջարկում է ընդհանրապես չվիճել, և նրանք դրա շուրջ վիճում են վեց ժամ։ Կիրակի օրը կակտուսը տնից բարձր է, իսկ գագաթին ապրում է մի {կենդանի}։ Քաղաքը կակտուսը հուշարձան է հայտարարում և {ածական} ցուցանակ կախում՝ «{ցանկացած բառ}»։ Հիմա զբոսաշրջիկները գալիս են անգամ {վայր}-ից, իսկ զույգը դիտմամբ վիճում է ամեն երեկո ժամը յոթին՝ բիզնեսի համար։"),
                Story("hy-love-06", Lang.Hy, StoryTheme.Love,
                    "Մատուցողի սիրտը",
                    "{@1ը} ռոմանտիկ ընթրիք է կազմակերպում {@2ի} համար և աղանդերին պատվիրում է հայտնի {ուտելիք#1}-ը։ Մատուցողը բերում է ամեն ինչ, բացի {#1}-ից, որովհետև սիրահարվել է դրան։ Ադմինիստրատորը ներողություն է խնդրում և կարդում մատուցողի բանաստեղծությունը՝ «{ցանկացած բառ}»։ {@1ը} փոխանակում է առաջարկում՝ {առարկա}, բայց մատուցողն ավելի ամուր է բռնում ափսեն։ Կեսգիշերին մատուցողը ծնկի է գալիս և ամուսնության առաջարկ անում {#1}-ին, իսկ խոհարարը բացականչում է՝ «{ածական}»։ {@1ը} և {@2ը} հրավեր են ստանում հարսանիքի և նստում են գդալների կողքին՝ {կենդանի}-ի նկարի տակ։"),
                Story("hy-work-01", Lang.Hy, StoryTheme.Work,
                    "Տպիչի աշխատավարձը",
                    "{@1ը} շտապ հաշվետվություն է տպում, բայց տպիչը հաշվետվության փոխարեն դիմում է տպում. ուզում է աշխատավարձ։ Պահանջները հետևյալն են՝ ամեն օր {ուտելիք#1} և սեփական {առարկա}։ Տնօրենը պահանջները {ածական} է համարում և մերժում, ու տպիչը ամեն էջին տպում է մեկ բառ՝ «{ցանկացած բառ#2}»։ {@1ը} տնից բերում է ամենակարևորը՝ {#1}, և տպիչն անմիջապես տպում է հաշվետվությունը։ Ժողովում տնօրենը քառասուն անգամ կարդում է «{#2}» և դա փայլուն ռազմավարություն անվանում։ Տպիչին առաջխաղացում են տալիս, նրա նոր աշխատասենյակը {վայր}-ում է, իսկ {@1ը} ամեն առավոտ բերում է նրա աշխատավարձը՝ {#1}։"),
                Story("hy-work-02", Lang.Hy, StoryTheme.Work,
                    "Ինքնավստահ հարցազրուցավարը",
                    "{@1ը} աշխատանքի հարցազրույցի է գալիս շուտ, բայց հարցազրույցը վարում է շատ ինքնավստահ մի {կենդանի#1}։ {#1}-ը պահանջում է հինգ րոպե նայել իր աչքերին և ասել՝ «{ցանկացած բառ#2}»։ {@2ը} միջանցքից շշնջում է, որ {#1}-ը կաշառք է սիրում, ու {@1ը} մի տուփ {ուտելիք} է մեկնում։ {#1}-ը վիրավորվում է, որովհետև տուփը {ածական} է, և հայտարարում, որ {@1ը} ազատված է, թեև դեռ չի էլ ընդունվել։ Հետո ներս է մտնում տնօրենը, և տնօրենը նույն {#1}-ն է։ Աշխատանքը ստանում է {@2ը}, իսկ {@1ը}՝ մխիթարական մրցանակ՝ {առարկա} և «{#2}»-ի գլխավոր պատասխանատուի պաշտոն։"),
                Story("hy-work-03", Lang.Hy, StoryTheme.Work,
                    "Ժողովներ ջրի տակ",
                    "Ղեկավարը հայտարարում է, որ երկուշաբթիից բոլոր ժողովներն անցկացվելու են ջրի տակ՝ {վայր}-ում։ {@1ը} գալիս է դիմակով, խողովակի փոխարեն՝ {առարկա#1}, իսկ սլայդները տպված են {ուտելիք}-ի վրա։ Սլայդները մեկ րոպեում լուծվում են, և {@1ը} ծրագիրը բացատրում է ժեստերով, իսկ օգնում է մի {կենդանի}։ Ոչ ոք ոչինչ չի հասկանում, ուրեմն ոչ ոք չի վիճում, և ծրագիրը հաստատվում է ռեկորդային արագությամբ։ {@2ը} հարցնում է, թե ինչու է այս ամենը, և ղեկավարը գրատախտակին գրում է՝ «{ցանկացած բառ}»։ Պարզվում է՝ ղեկավարը պարզապես ժողովներ էր ուզում, որտեղ մի ամբողջ ժամ ոչ ոք չի կարող խոսել։ Հիմա ամբողջ ընկերությունը լողալով է գնում աշխատանքի, իսկ {@1ը} դառնում է «{#1}» բաժնի ղեկավար։"),
                Story("hy-work-04", Lang.Hy, StoryTheme.Work,
                    "Պրակտիկանտը",
                    "Նոր պրակտիկանտն ակնհայտորեն փողկապով կատու է, բայց կադրերի բաժինը պնդում է, որ փաստաթղթերը կարգին են։ Առաջին իսկ օրը պրակտիկանտը քնում է ստեղնաշարի վրա և բոլոր հաճախորդներին նամակ ուղարկում՝ «{ցանկացած բառ#1}»։ Գլխավոր հաճախորդը մեկ րոպեում պատասխանում է՝ «{ածական}», և երեք տարվա պայմանագիր ստորագրում։ {@1ը} պրակտիկանտին աղյուսակներ է սովորեցնում, բայց պրակտիկանտը սեղանից գցում է մի {առարկա} և երկար նայում {@1ին}։ Ուրբաթ օրն արդեն պրակտիկանտը տնօրեն է, և նրա աշխատասենյակը {վայր}-ում է։ {@1ը} հիմա տնօրենի օգնականն է և ուղիղ ժամը վեցին բերում է {ուտելիք} ու «{#1}» բոլոր նամակների տպված օրինակները։"),
                Story("hy-work-05", Lang.Hy, StoryTheme.Work,
                    "Սուրճի գործադուլը",
                    "Երկուշաբթի օրը գրասենյակի սուրճի մեքենան գործադուլ է հայտարարում և պահանջների ցուցակ փակցնում։ Նա ուզում է {ածական} անուն, շաբաթական մեկ {ուտելիք#2} և պատին {կենդանի}-ի լուսանկար։ {@1ը} արդեն {թիվ} տարի միայն թեյ է խմում, այնպես որ բանակցությունների գնում է {@1ը}։ {@1ը} հաշտության նվեր է առաջարկում՝ {առարկա}, և մեքենան պատասխանում է մեկ բառով՝ «{ցանկացած բառ#1}»։ Ճաշին ամբողջ գրասենյակը տնօրենի դռան մոտ վանկարկում է՝ «{#1}»։ Պարզվում է՝ պահանջները գրել է հենց տնօրենը, որովհետև երեք տարի աշխատավարձի բարձրացում չի ստացել։ Տնօրենը ստանում է բարձրացում, մեքենան՝ {#2}, իսկ {@1ը} մենակ թեյ է խմում {վայր}-ում։"),
                Story("hy-work-06", Lang.Hy, StoryTheme.Work,
                    "Ոչ այն տեսախցիկը",
                    "Կարևոր տեսազանգից հինգ րոպե առաջ {@1ը} միացնում է տեսախցիկը, բայց դեմքի փոխարեն էկրանին մի {կենդանի#1} է։ Ղեկավարը միանում է, նայում էկրանին և ասում ընդամենը մեկ բառ՝ «{ածական}»։ {@1ը} երկու անգամ վերագործարկում է նոութբուքը, և հիմա կադրում {@2ն} է՝ {վայր}-ում նստած և {ուտելիք} վայելելիս։ Ղեկավարին դա էլ է դուր գալիս, և եռամսյակային հաշվետվությունը հիմա ներկայացնում է {@2ը}։ Հանկարծ թարթում է հենց ղեկավարի տեսախցիկը, և բոլորը տեսնում են, որ ղեկավարը {առարկա} է, այն էլ արդեն երկու տարի։ Առաջխաղացում ստանում է {#1}-ը, և հիմա {@1ը} ամեն երկուշաբթի ժամը իննին հաշվետվություն է ներկայացնում նրան։"),
                Story("hy-family-01", Lang.Hy, StoryTheme.Family,
                    "Տատիկը եթերում",
                    "{@1ը} չի կարողանում քնել, որովհետև ամեն գիշեր կեսգիշերին պատի հետևից ինչ-որ ձայն {ուտելիք#1}-ի բաղադրատոմս է կարդում։ {@1ը} պատին գրություն է փակցնում՝ «{ցանկացած բառ#2}», և նորից պառկում։ Հաջորդ գիշեր ձայնը եթերում կարդում է գրությունը և շնորհակալություն հայտնում {ածական} գաղափարի համար։ Պատի հետևում {@1ը} գտնում է տատիկին, միկրոֆոն և գաղտնի ռադիոկայան՝ տասնմեկ հազար ունկնդրով։ Հիմա եթերում երկուսն են՝ տատիկը և {@1ը}, իսկ առաջին հյուրը մի {կենդանի} է, որը հաստատ կարծիք ունի {#1}-ի մասին։ Հաղորդումն այժմ կոչվում է «{#2}», իսկ {@1ը} ցերեկը քնում է {առարկա}-ի պես։"),
                Story("hy-family-02", Lang.Hy, StoryTheme.Family,
                    "Կատվի բողոքը",
                    "{@1ը} հանգիստ կիրակի է ուզում, բայց կատուն պաշտոնական բողոք է ներկայացնում ընտանիքի դեմ։ Բողոքը տասներկու էջ է և վերնագրված է՝ «{ցանկացած բառ#1}»։ Կատուն նախաճաշին {ուտելիք} է պահանջում, իսկ քնելու համար՝ {առարկա}, և ամեն ինչ կնքված է իրավաբանի կողմից։ {@1ը} գնում է կենդանիների խանութ՝ հարցը լուծելու, և հերթում նույն բողոքով կանգնած է հարևանների {կենդանի#2}-ը։ Պարզվում է՝ երկու բողոքն էլ գրել է {#2}-ը, իսկ կատուն միայն ստորագրել է։ Հիմա ընտանիքը ամեն առավոտ բարձրաձայն կարդում է «{#1}», իսկ {#2}-ը ընթերցումը գնահատում է՝ «{ածական}»։"),
                Story("hy-family-03", Lang.Hy, StoryTheme.Family,
                    "Բախտավոր շունը",
                    "Ընտանիքի շունը վիճակախաղ է շահում և հրաժարվում է կիսվել։ Առաջին հերթին նա իրեն ոսկե {առարկա#1} է գնում և {ուտելիք}-ի ցմահ պաշար։ {@1ը} փորձում է մոտենալ և նոր {ածական} վզկապ է նվիրում, բայց շունը փաստաբան է վարձում։ Փաստաբանը մի {կենդանի} է, և վճարը րոպեական է։ Շաբաթվա վերջին շունը գնում է ամբողջ տունը և ընտանիքին տեղափոխում ավտոտնակ՝ {#1}-ի կողքին։ Հիմա {@1ը} ամեն ուրբաթ վարձ է վճարում, և շունն այն ընդունում է միայն խոնարհումով ու «{ցանկացած բառ}» բառերով։"),
                Story("hy-family-04", Lang.Hy, StoryTheme.Family,
                    "Պապիկի ստարտափը",
                    "Պապիկն ավտոտնակում ստարտափ է բացում՝ բանալիներ գտնող սարք, որն արտաքինից {առարկա} է։ {@1ը} ներդրողներ է հրավիրում, նրանք գալիս են {ածական} մեքենայով և նստում {ուտելիք}-ի արկղերի վրա։ Ցուցադրությունը սկսվում է, և սարքը տասնմեկ վայրկյանում գտնում է պապիկի բանալիները՝ {վայր}-ում։ Ներդրողները խնդրում են գտնել նաև իրենց բանալիները, բայց սարքն աշխատում է միայն պապիկի հետ։ Ներդրողներն այնուամենայնիվ գնում են ընկերությունը, և պապիկին էլ հետը, քանի որ առանց նրա սարքը չի աշխատում։ Հիմա պապիկը բիզնես դասով թռչում է աշխարհով մեկ, բանալիներ է գտնում և {@1ին} բացիկներ ուղարկում՝ «{ցանկացած բառ}» գրությամբ։"),
                Story("hy-family-05", Lang.Hy, StoryTheme.Family,
                    "Սառնարանը գիտի",
                    "Սառնարանը սկսում է գրություններ թողնել ընտանիքի բոլոր անդամների սովորությունների մասին։ Առաջին գրությունը՝ «{@1ը} գիշերվա ժամը 3:10-ին կերավ վերջին {ուտելիք#1}-ը»։ {@1ը} հաջորդ {#1}-ը թաքցնում է ավտոտնակում՝ {առարկա}-ի հետևում, որտեղ քնած է մի {կենդանի}։ Երկրորդ գրությունը հայտնում է, թե որտեղ է թաքստոցը, և ավելացնում մեկ բառ՝ «{ածական}»։ Այդ ժամանակ {@1ը} որոշում է անջատել սառնարանը, և հայտնվում է երրորդ գրությունը՝ «{ցանկացած բառ}»։ Գիշերը {@1ը} մտնում է խոհանոց և տեսնում, թե ինչպես է {@2ը} սառնարանի ձեռագրով գրություններ գրում։ {@2ը} խոստովանում է՝ այլ կերպ վերջին {#1}-ը {@1ից} փրկել հնարավոր չէր։"),
                Story("hy-family-06", Lang.Hy, StoryTheme.Family,
                    "Մեջքով դեպի տեսախցիկը",
                    "Տատիկի ծննդյան օրվա համար {@1ը} ընտանեկան լուսանկարահանում է պատվիրում «{ցանկացած բառ#1}» ստուդիայում։ Լուսանկարիչը վախենում է դեմքերից, ուստի ամբողջ ընտանիքը կանգնում է մեջքով դեպի տեսախցիկը։ {@1ը} փորձում է օգնել և ամեն մեկի դեմքը ծածկում է մի {առարկա}-ով։ Լուսանկարիչը հանգստանում է և հավասարակշռության համար առաջին շարքում նստեցնում է նաև մի {կենդանի#2}։ Տատիկը նկարը կախում է բազմոցի վերևում և ասում, որ ընտանիքը երբեք այսքան {ածական} չի երևացել։ Հյուրերը նկարում ճանաչում են միայն {#2}-ին, իսկ «{#1}» ստուդիան ընտանիքին նվեր կտրոն է ուղարկում՝ {ուտելիք}-ի համար։"),
                Story("hy-fairy-01", Lang.Hy, StoryTheme.Fairy,
                    "Վիշապի հացատունը",
                    "Վիշապը հացատուն է բացում, բայց սարսափելի վախենում է մկներից։ {@1ը} աշխատում է վաճառասեղանի մոտ, և առաջին գնորդը տորթ է պատվիրում {կենդանի}-ի տեսքով։ Ամեն առավոտ վիշապը ստուգում է բոլոր անկյունները և գոռում՝ «{ցանկացած բառ#1}»։ Մի օր {@1ը} ալյուրի մեջ մուկ է գտնում՝ թաթերում {ուտելիք}։ Վիշապը կրակ է փռշտում, և ամբողջ հացը վերածվում է {ածական} {առարկա}-ի։ Պարզվում է՝ մուկն արդեն {թիվ} տարի թխում է ամբողջ հացը, որովհետև վիշապի թաթերը չափազանց մեծ են խմորի համար։ Հիմա հացատունը ղեկավարում է մուկը, իսկ դռան վերևում ցուցանակ է՝ «{#1}»։"),
                Story("hy-fairy-02", Lang.Hy, StoryTheme.Fairy,
                    "Ծույլ ասպետը",
                    "{@1ը} կառավարում է փոքրիկ թագավորություն և ասպետ է վարձում վիշապի դեմ, բայց ասպետը սարսափելի ծույլ է, և նրա մականունն էլ «{ածական}» է։ Ասպետը համաձայն է, բայց նախ՝ քնել, իսկ նրա միակ անկողինը {առարկա#1} է։ Կեսօրին վիշապը գալիս է, տեսնում քնած ասպետին և քաղաքավարի սպասում՝ հետը {ուտելիք}։ Երեկոյան վիշապը ձանձրանում է և պառկում ասպետի կողքին։ {@1ը} գտնում է երկուսին էլ խռմփացնելիս և հաշտություն հայտարարում, իսկ հաշտության պայմանագիրը կոչվում է «{ցանկացած բառ}»։ Հիմա ամեն երեքշաբթի քնի ազգային օր է, և վիշապը {#1}-ը պաշտպանում է մի {կենդանի}-ից։"),
                Story("hy-fairy-03", Lang.Hy, StoryTheme.Fairy,
                    "Քաղաքավարի կահույքը",
                    "Կախարդի հմայքը ամբողջ գյուղը վերածում է շատ քաղաքավարի կահույքի։ {@1ը} արթնանում է աթոռ դարձած, իսկ {@2ը}՝ {առարկա}։ Ամեն աթոռ, որի վրա նստում են, ասում է՝ «{ցանկացած բառ#1}», և ոչ ոք չի կարողանում հանգստանալ։ {@1ը} ցատկոտելով գնում է կախարդի մոտ բողոքելու, իսկ նա {ուտելիք} է վայելում մի սեղանի մոտ, որը հրաժարվում է սեղան լինել։ Սեղանը շուռ է գալիս, կախարդն ընկնում է ջրափոսի մեջ և բացականչում՝ «{ածական}»։ Նա խոստովանում է՝ դա վրեժ էր այն բանի համար, որ {թիվ} տարի բոլորը ոտքերը դնում էին բազմոցին։ Հմայքը վերանում է, բայց ամեն աթոռ դեռ ասում է «{#1}», հատկապես այն մեկը, որ նման է {կենդանի}-ի։"),
                Story("hy-fairy-04", Lang.Hy, StoryTheme.Fairy,
                    "Քվեարկիր գորտի օգտին",
                    "Խոսող գորտն առաջադրվում է քաղաքապետի պաշտոնում, և {@1ը} դառնում է նրա քարոզարշավի ղեկավարը։ Գորտը խոստանում է բոլորին անվճար {ուտելիք#1} և լճակ ամեն {վայր}-ում։ Բանավեճի ժամանակ գորտը միայն կռկռում է, և {@1ը} թարգմանում է՝ «{ցանկացած բառ}»։ Մրցակիցը՝ մի {կենդանի}, պահանջում է ապացուցել, որ գորտը կարդալ գիտի։ {@1ը} գորտին տալիս է ձեռքի տակ եղածը՝ {առարկա}, և գորտը կարդում է գլխիվայր։ Գորտն այնուամենայնիվ հաղթում է, և առաջին օրենքով ամեն երեքշաբթի «{#1}»-ի օր է՝ {ածական} երաժշտությամբ։"),
                Story("hy-fairy-05", Lang.Hy, StoryTheme.Fairy,
                    "Երեք ճշգրիտ ցանկություն",
                    "{@1ը} ճրագ է գտնում, և ջինը երեք ցանկություն է առաջարկում, բայց ամեն ինչ հասկանում է բառացի։ {@1ը} հարստություն է խնդրում, և ջինը բերում է Հարստություն անունով մի {կենդանի#1}։ Հետո {@1ը} ծովափին տուն է ուզում, և ջինը ծովը տեղափոխում է {վայր}-ի մեջ։ Վերջին ցանկության համար {@1ը} տասներկու էջանոց {ածական} նամակ է գրում, որ ոչինչ սխալ չգնա։ Ջինը կարդում է, ասում՝ «{ցանկացած բառ}», և {@1ը} վերածվում է {առարկա}-ի։ Հիմա {@1ը} կանգնած է ջինի դարակին, իսկ {#1}-ը ամեն առավոտ նրան փոշուց մաքրում է {ուտելիք}-ով։"),
                Story("hy-misc-01", Lang.Hy, StoryTheme.Misc,
                    "Դոլմա տիեզերքից",
                    "Բակում տիեզերանավ է վայրէջք կատարում, և այլմոլորակայիններին մի բան է պետք՝ սովորել դոլմա պատրաստել։ {@1ը} սկսում է դասը, բայց խաղողի տերևների փոխարեն նրանք բերել են {առարկա#1}։ Նրանք միսը փաթաթում են {#1}-ի մեջ, և խոհանոցը լցվում է {ածական} ծխով։ {@2ը} վազում է հարևանի հետևից, և նա գալիս է {թիվ} տարվա փորձով ու իր {կենդանի}-ով։ Պարզվում է՝ հարևանն էլ է այլմոլորակային. եկել էր դոլմայի դասի և մնացել։ Այլմոլորակայինները բաղադրատոմսին գաղտնի բաղադրիչ են ավելացնում՝ {ուտելիք}, և գոհ թռչում են տուն։ Հիմա նրանց մոլորակում ամեն տարի դոլմայի փառատոն է «{ցանկացած բառ}» խառնարանում, և {@1ը} պատվավոր հյուր է։"),
                Story("hy-misc-02", Lang.Hy, StoryTheme.Misc,
                    "Գուլպաների հերոսը",
                    "{@1ը} սուպերհերոս է, և նրա միակ գերուժը կորած գուլպաներ գտնելն է։ Քաղաքը ոչինչ չի վճարում, միայն երեքշաբթի օրերին տալիս է {ուտելիք}։ Մի օր զանգում է քաղաքապետը. ձախ գուլպան կորել է, իսկ մինչև ելույթը մնացել է {թիվ} րոպե։ {@1ը} այն գտնում է տասնմեկ վայրկյանում՝ {վայր}-ում, մի {առարկա}-ի մեջ։ Քաղաքապետը հրաժարվում է հագնել, որովհետև գուլպայից {կենդանի}-ի հոտ է գալիս, ու {@1ը} այն ցողում է {ածական} օծանելիքով։ Օծանելիքն այնքան ուժեղ է, որ քաղաքի բոլոր կորած գուլպաները վազում են հոտի հետևից։ Հիմա {@1ը} ինը հազար գուլպա ունի և ոչ մի զույգ, իսկ թերթերը դա անվանում են «{ցանկացած բառ}»։"),
                Story("hy-misc-03", Lang.Hy, StoryTheme.Misc,
                    "Երեկվա վերելակը",
                    "{@1ի} շենքի վերելակը խրվում է երկու ժամային գոտիների միջև։ Ձախ դռան հետևում երկուշաբթի առավոտ է, իսկ աջի հետևում՝ անցած շաբաթվա խնջույքը, որտեղ սեղանին {ուտելիք} է։ {@1ը} մտնում է խնջույք, և ամեն ինչ {ածական} է, մինչև ղեկավարը զանգում է հաշվետվության համար։ Վարպետը գալիս է հաջորդ երեքշաբթիից՝ հետը մի {կենդանի#1} և {առարկա}։ Նա սեղմում է մեկ կոճակ, և հիմա վերելակը բացվում է միայն {վայր}-ում, այն էլ մեկ օր շուտ։ {@1ը} շարունակում է օգտվել վերելակից և այլևս երբեք չի ուշանում, որովհետև աշխատանքի է հասնում երեկ՝ {#1}-ի հետ։"),
                Story("hy-misc-04", Lang.Hy, StoryTheme.Misc,
                    "Արձանը բողոքում է",
                    "Գիշերը թանգարանի արձանը կենդանանում է և բողոք գրում այցելուների դեմ։ Նրանք մատով ցույց են տալիս, դիպչում են, իսկ մեկն էլ նրա քիթը {ածական} է անվանել։ {@1ը} գիշերային պահակ է և փորձում է արձանը հանգստացնել թեյով ու {ուտելիք}-ով։ Արձանը պահանջում է իրեն տեղափոխել {վայր}-ը, որտեղ ոչ ոք իրեն չի նայի։ {@1ը} տեղափոխում է, և առավոտյան {թիվ} մարդ հերթ է կանգնում՝ նրան այնտեղ տեսնելու։ Հիմա արձանը տոմսեր է վաճառում և իր դեմքով հուշանվեր՝ {առարկա}։ Նա թանգարանից ավելի շատ է վաստակում, իսկ {@1ը} հսկում է նրան՝ ձեռքին «{ցանկացած բառ}» ցուցանակ։"),
                Story("hy-misc-05", Lang.Hy, StoryTheme.Misc,
                    "Գնդակը թոշակի է գնում",
                    "Եզրափակչի կեսին գնդակը հայտարարում է, որ թոշակի է գնում։ Նա գլորվում է դեպի նստարանը, հագնում մի {առարկա#1} և {ուտելիք} խնդրում։ {@1ը}՝ թիմի ավագը, փորձում է գնդակի փոխարեն խաղալ մի {կենդանի}-ով, բայց մրցավարն ասում է, որ դա խախտում է «{ցանկացած բառ}» կանոնը։ Այդ ժամանակ {@1ը} գնդակին առաջարկում է {ածական} պայմանագիր և արձակուրդ {վայր}-ում։ Գնդակը համաձայնում է խաղալ վերջին րոպեն և դիտմամբ գոլ է խփում սեփական դարպասը։ Հիմա գնդակը մրցակից թիմի մարզիչն է և ամեն խաղին կրում է {#1}-ը։"),
                Story("ru-travel-01", Lang.Ru, StoryTheme.Travel,
                    "Чемодан фокусника",
                    "{@1} открывает чемодан из аэропорта, а там вместо одежды цилиндр, записка «{любое слово}» и ещё одна вещь: {предмет#1}. Надеть больше нечего, и {@1} идёт на ужин в отеле в цилиндре. {@1} снимает цилиндр, чтобы поздороваться, и оттуда выпрыгивает {животное} — прямо в тарелку, где лежит {еда}. Директор отеля кричит: «{прилагательное}!» — и предлагает контракт на каждый вечер. А в это время знаменитый фокусник выступает {где? например: в бане} в чужой пижаме, и зал в восторге. В аэропорту они меняются чемоданами, но вещь под названием {#1} не отдаёт никто."),
                Story("ru-travel-02", Lang.Ru, StoryTheme.Travel,
                    "Честный экскурсовод",
                    "{@1} покупает экскурсию по старой крепости, но экскурсовод явно всё выдумывает. По его словам, башню построили в 1704 году, чтобы хранить там одно: {еда#1}. {@1} просит доказательств, и экскурсовод показывает на находку: {предмет#2}, «та самая крышка». Двадцать туристов фотографируют находку, и у одного из них на плече сидит {животное}. {@1} жалуется в кассу, но кассир только пожимает плечами: «{любое слово}». Через год {@1} возвращается, а на воротах новая табличка: «Музей. {#1}». Экскурсовод теперь директор, у вещи под названием {#2} отдельный зал, а в книге отзывов одно слово: «{прилагательное}»."),
                Story("ru-travel-03", Lang.Ru, StoryTheme.Travel,
                    "Сосед по номеру",
                    "После двенадцати часов в дороге {@1} заходит в номер, а на единственной кровати спит {животное#1}. Администратор смотрит в компьютер: номер оплачен ещё в 2019 году, и оплата — {еда}. {@1} предлагает делить кровать, но на ней уже висит табличка: «{любое слово}». Так что {@1} спит в ванне, а вместо подушки — {предмет}. Утром {#1} получает завтрак в постель, а {@1} — счёт за ванну. {#1} оставляет отзыв: пять звёзд, номер «{прилагательное}», но гость в ванной очень шумный."),
                Story("ru-travel-04", Lang.Ru, StoryTheme.Travel,
                    "Навигатор-загадка",
                    "{@1} берёт машину напрокат, а навигатор в ней говорит только загадками. «Сверни там, где {животное} без тени», — говорит он, и {@1} целый час сворачивает у каждой фермы. «Остановись там, где спит {предмет}», — и {@1} останавливается у мебельного магазина. Наконец {@2} отгадывает одну: ответ — «{любое слово#1}», и дорога ведёт {куда? например: на Луну}. Там шарики, торт, на торте — {еда}, и растяжка с надписью «{#1}». Это день рождения навигатора, и он готовил этот маршрут лет {число}. {@1} остаётся на торт, и навигатор наконец говорит прямо: «Налево. И в следующий раз с подарком: {предмет}»."),
                Story("ru-travel-05", Lang.Ru, StoryTheme.Travel,
                    "У палатки есть мнение",
                    "{@1} едет {куда? например: на Луну} ради одной тихой ночи у озера, но у новой палатки есть мнение. Ровная поляна не подходит: трава пахнет так, будто здесь была {еда}. Лес тоже не подходит: оттуда на палатку косо смотрит {животное}. {@1} тащит палатку на холм, и она соглашается при одном условии, а условие такое: {предмет#1}. В полночь палатка впускает ещё три палатки полюбоваться видом, и вид, по их мнению, «{прилагательное}». К утру {@1} спит снаружи, а палатки по очереди обнимают одно: {#1}."),
                Story("ru-travel-06", Lang.Ru, StoryTheme.Travel,
                    "Маленький круиз",
                    "{@1} покупает роскошный круиз со ста развлечениями, но корабль оказывается лодкой с вёслами. Капитан выдаёт вёсла и список: развлечение первое — грести, второе — {действие, например: танцевать}. Весь день за ними плывёт огромный лайнер, и пассажиры машут флагами и кричат: «{любое слово}!» На закате капитан лайнера объявляет: у них закончилось одно — {еда#1}, а последняя коробка лежит в лодке. {@1} меняет коробку на весь лайнер, вместе с ключами. Теперь {@1} плывёт на лайнере {куда? например: на Луну}, а старый капитан гребёт следом, и с ним {предмет} и последняя коробка: {#1}."),
                Story("ru-love-01", Lang.Ru, StoryTheme.Love,
                    "Столик на четверых",
                    "{@1} хочет идеальное первое свидание и бронирует столик в ресторане «{любое слово#1}». Но за соседним столиком уже прячется за меню мама второго человека, а на её тарелке — {еда}. {@1} заглядывает под стол: там сидит собственная мама, а в руках на всякий случай {предмет}. Мамы замечают друг друга и вслух ставят свиданию оценки, как жюри на выставке, где главный участник — {животное}. К десерту мамы уже обменялись телефонами и планируют поездку {куда? например: на Луну}. Теперь мамы каждую пятницу ужинают в «{#1}», а {@1} и второй человек приглашения не получают."),
                Story("ru-love-02", Lang.Ru, StoryTheme.Love,
                    "Голубиный тест",
                    "{@1} встаёт на одно колено {где? например: в бане}, чтобы сделать предложение, но голубь крадёт кольцо и улетает. Во второй раз кольцо спрятано внутри, а снаружи — {еда#1}, но голубь съедает всё целиком. В третий раз {@1} закрывается щитом, а щит — {предмет}, но голубь возвращается с подкреплением: {животное}. Тут бабушка на скамейке свистит, и оба голубя садятся ей на шляпу. Она тренирует голубей проверять каждое предложение здесь, и {@1} проверку проходит: «{любое слово}!» На свадьбе голубь приносит кольца — снова внутри, а снаружи снова {#1}, и прилетает минута в минуту."),
                Story("ru-love-03", Lang.Ru, StoryTheme.Love,
                    "Мэтч",
                    "{@1} получает мэтч в приложении для знакомств: торговый автомат {где? например: в бане}. В анкете автомата: любит одно — {еда#1}, ненавидит мелочь, ищет что-то «{прилагательное}». На первое свидание {@1} приносит цветы, а автомат выдаёт ответный подарок: {#1} и пластиковая фигурка, на ней — {животное}. Свидание идёт хорошо, {@1} наклоняется ближе, и автомат вызывает охрану. Охранник приходит, видит автомат и вздыхает: «{любое слово}, опять ты». Охранник — бывший автомата, и теперь {@1} каждое утро покупает одно и то же — {#1}, — просто чтобы охранник ревновал."),
                Story("ru-love-04", Lang.Ru, StoryTheme.Love,
                    "Квартира 14",
                    "{@1} пишет любовное письмо человеку из квартиры 41, но письмо по ошибке попадает в квартиру 14. Ответ приходит на следующий день от бабушки, и в нём рецепт, а блюдо — {еда#1}. {@1} пишет, чтобы всё объяснить, а бабушка отвечает четырьмя страницами о своём питомце: {животное}. Три месяца они переписываются по вторникам: о погоде, о поездке {куда? например: на Луну} и о главном — {#1}. Потом в дверь стучит человек из 41-й, в руках {предмет}: бабушка — родственница и уже всё рассказала. Теперь {@1} и человек из 41-й — пара, но по вторникам {@1} всё равно пишет в квартиру 14 и подписывается: «{любое слово}»."),
                Story("ru-love-05", Lang.Ru, StoryTheme.Love,
                    "Кактус для ссор",
                    "На годовщину {@1} дарит кактус, который растёт каждый раз, когда пара ссорится. В первый вечер они ссорятся из-за ерунды — {еда}, и к утру кактус выше, чем {предмет}. {@1} предлагает вообще больше не ссориться, и они ссорятся из-за этого шесть часов. К воскресенью кактус выше дома, а на верхушке живёт {животное}. Город объявляет кактус памятником и вешает табличку: «{любое слово}». Теперь у кактуса толпы туристов и отзывы «{прилагательное}», а пара ссорится нарочно, каждый вечер в семь, ради бизнеса."),
                Story("ru-love-06", Lang.Ru, StoryTheme.Love,
                    "Сердце официанта",
                    "{@1} устраивает романтический ужин, а на десерт заказывает знаменитое блюдо: {еда#1}. Официант приносит всё, кроме одного — {#1}: он влюблён в этот десерт. Администратор извиняется и зачитывает стихи официанта, посвящённые десерту: «{любое слово}». {@1} предлагает обмен — {предмет}, но официант только крепче держит тарелку. В полночь официант делает десерту предложение на одном колене, а шеф-повар кричит: «{прилагательное}!» {@1} и {@2} получают приглашение на свадьбу и сидят рядом с ложками, под картиной: {животное} в рамке."),
                Story("ru-work-01", Lang.Ru, StoryTheme.Work,
                    "Зарплата принтера",
                    "{@1} срочно печатает отчёт, но принтер вместо отчёта выдаёт заявление: он хочет зарплату. Требования такие: каждый день — {еда#1}, а ещё своя вещь: {предмет}. Директор называет требования «{прилагательное}» и отказывает, и принтер печатает на каждой странице одно слово: «{любое слово#2}». {@1} приносит из дома главное — {#1}, и принтер мгновенно печатает отчёт. На совещании директор сорок раз читает «{#2}» и называет это гениальной стратегией. Принтера повышают, теперь у него кабинет {где? например: в бане}, а {@1} каждое утро приносит ему зарплату: {#1}."),
                Story("ru-work-02", Lang.Ru, StoryTheme.Work,
                    "Уверенный интервьюер",
                    "{@1} приходит на собеседование пораньше, но собеседование ведёт {животное#1}, и держится очень уверенно. {#1} требует пять минут смотреть в глаза и сказать: «{любое слово#2}». {@2} шепчет из коридора, что {#1} любит взятки, и {@1} протягивает коробку, а в ней — {еда}. {#1} обижается: коробка, видите ли, «{прилагательное}», — и объявляет: «Вы уволены», хотя договор ещё даже не подписан. Тут входит директор, и директор — тоже {#1}. Работу получает {@2}, а {@1} — утешительный приз: {предмет} и должность «главный по слову {#2}»."),
                Story("ru-work-03", Lang.Ru, StoryTheme.Work,
                    "Совещания под водой",
                    "Начальник объявляет: с понедельника все совещания проходят под водой, {где? например: в бане}. {@1} приходит в маске, вместо трубки — {предмет#1}, а слайды распечатаны на одном материале: {еда}. Слайды за минуту растворяются, и {@1} объясняет план жестами, а помогает {животное}. Никто ничего не понимает, а значит, никто не спорит, и план утверждают рекордно быстро. {@2} спрашивает, зачем всё это, и начальник пишет на доске: «{любое слово}». Просто начальник хотел совещаний, на которых целый час никто не может говорить. Теперь вся компания плавает на работу, а {@1} теперь начальник отдела под названием «{#1}»."),
                Story("ru-work-04", Lang.Ru, StoryTheme.Work,
                    "Стажёр",
                    "Новый стажёр — явно кот в галстуке, но отдел кадров уверяет, что документы в порядке. В первый же день стажёр засыпает на клавиатуре и отправляет всем клиентам письмо: «{любое слово#1}». Главный клиент отвечает через минуту — «{прилагательное}!» — и подписывает контракт на три года. {@1} учит стажёра таблицам, но стажёр сталкивает со стола одну вещь — {предмет} — и пристально смотрит. К пятнице стажёр уже директор, и кабинет у него {где? например: в бане}. {@1} теперь ассистент директора и ровно в шесть приносит завтрак — {еда} — и распечатки всех писем «{#1}»."),
                Story("ru-work-05", Lang.Ru, StoryTheme.Work,
                    "Кофейная забастовка",
                    "В понедельник кофемашина в офисе объявляет забастовку и вешает список требований. Она хочет имя, и имя должно быть «{прилагательное}», раз в неделю — {еда#2}, и фото на стене: {животное}. {@1} лет {число} пьёт только чай, поэтому на переговоры идёт {@1}. {@1} предлагает мирный подарок — {предмет}, и машина отвечает одним словом: «{любое слово#1}». К обеду весь офис скандирует «{#1}» у двери директора. Оказывается, требования написал сам директор: три года без повышения. Директор получает повышение, машина — {#2}, а {@1} пьёт чай в одиночестве {где? например: в бане}."),
                Story("ru-work-06", Lang.Ru, StoryTheme.Work,
                    "Не та камера",
                    "За пять минут до важного созвона {@1} включает камеру, а в ней вместо лица — {животное#1}. Начальник подключается, смотрит на экран и говорит одно слово: «{прилагательное}!» {@1} дважды перезагружает ноутбук, и теперь в кадре {@2}: сидит {где? например: в бане} и ест, а на тарелке — {еда}. Начальнику нравится и это, и квартальный отчёт теперь представляет {@2}. Тут мигает камера самого начальника, и все видят, что начальник — это {предмет}, причём уже два года. Повышение получает {#1}, и теперь {@1} каждый понедельник в девять отчитывается перед новым начальником."),
                Story("ru-family-01", Lang.Ru, StoryTheme.Family,
                    "Бабушка в эфире",
                    "{@1} не может уснуть: каждую ночь в полночь голос за стеной читает рецепт, и блюдо всегда одно — {еда#1}. {@1} приклеивает к стене записку «{любое слово#2}» и снова ложится. Следующей ночью голос читает записку в эфире и благодарит слушателя за идею — «{прилагательное}». За стеной {@1} находит бабушку, микрофон и пиратскую радиостанцию с одиннадцатью тысячами слушателей. Теперь в эфире двое: бабушка и {@1}, а первый гость — {животное} с твёрдым мнением о главном: {#1}. Передача теперь называется «{#2}», а {@1} спит днём, как {предмет}."),
                Story("ru-family-02", Lang.Ru, StoryTheme.Family,
                    "Жалоба кота",
                    "{@1} мечтает о тихом воскресенье, но кот подаёт на семью официальную жалобу. Жалоба на двенадцать страниц, а называется она «{любое слово#1}». Кот требует на завтрак одно — {еда}, а для сна вот что: {предмет}, и всё заверено юристом. {@1} идёт в зоомагазин уладить дело, а там в очереди с той же жалобой стоит питомец соседей: {животное#2}. Оказывается, автор обеих жалоб — {#2}, а кот только подписывал. Теперь семья каждое утро вслух читает «{#1}», а {#2} оценивает чтение: «{прилагательное}»."),
                Story("ru-family-03", Lang.Ru, StoryTheme.Family,
                    "Счастливая собака",
                    "Семейная собака выигрывает в лотерею и отказывается делиться. Первым делом она покупает себе золотую вещь — {предмет#1} — и пожизненный запас: {еда}. {@1} пытается подлизаться и дарит новый ошейник — «{прилагательное}», но собака нанимает адвоката. Адвокат — {животное}, и оплата у него поминутная. К выходным собака покупает весь дом и переселяет семью в гараж, где стоит {#1}. Теперь {@1} каждую пятницу платит аренду, и собака принимает деньги, только если {@1} кланяется и говорит: «{любое слово}»."),
                Story("ru-family-04", Lang.Ru, StoryTheme.Family,
                    "Стартап дедушки",
                    "Дедушка открывает в гараже стартап: прибор для поиска ключей, а с виду это {предмет}. {@1} зовёт инвесторов, они приезжают на машине «{прилагательное}» и садятся на коробки, а в коробках — {еда}. Начинается демонстрация, и прибор за одиннадцать секунд находит ключи дедушки: они {где? например: в бане}. Инвесторы просят найти и их ключи, но прибор работает только с дедушкой. Инвесторы всё равно покупают компанию — и дедушку тоже, раз без него прибор не работает. Теперь дедушка летает первым классом {куда? например: на Луну}, ищет ключи и шлёт {@1} открытки с одним словом: «{любое слово}»."),
                Story("ru-family-05", Lang.Ru, StoryTheme.Family,
                    "Холодильник всё знает",
                    "Холодильник начинает оставлять записки о привычках всей семьи. Первая записка: «{@1} в 3:10 ночи съедает последнее: {еда#1}». {@1} прячет следующую порцию — {#1} — в гараже за одной вещью: {предмет}, а рядом спит {животное}. Вторая записка сообщает, где тайник, и добавляет одно слово: «{прилагательное}». Тогда {@1} решает выключить холодильник, и появляется третья записка: «{любое слово}». Ночью {@1} заходит на кухню, а там {@2} пишет записки почерком холодильника. {@2} признаётся: иначе последнюю порцию — {#1} — от {@1} не спасти."),
                Story("ru-family-06", Lang.Ru, StoryTheme.Family,
                    "Спиной к камере",
                    "На день рождения бабушки {@1} заказывает семейную фотосессию в студии «{любое слово#1}». Фотограф боится лиц, поэтому вся семья позирует спиной к камере. {@1} пытается помочь и закрывает каждое лицо одной вещью: {предмет}. Фотограф успокаивается и для равновесия сажает в первый ряд ещё и это: {животное#2}. Бабушка вешает фото над диваном и говорит, что семья ещё никогда не выглядела так: «{прилагательное}». Гости узнают на фото только одного — {#2}, а студия «{#1}» дарит семье купон, и на нём — {еда}."),
                Story("ru-fairy-01", Lang.Ru, StoryTheme.Fairy,
                    "Пекарня дракона",
                    "Дракон открывает пекарню, но до ужаса боится мышей. {@1} работает за прилавком, и первый покупатель заказывает торт, а форма у торта — {животное}. Каждое утро дракон проверяет все углы и кричит: «{любое слово#1}». Однажды {@1} находит в муке мышь, а у мыши в лапах — {еда}. Дракон чихает огнём, и весь хлеб превращается вот во что: {предмет}. Оказывается, мышь печёт весь хлеб уже лет {число}: у дракона лапы слишком большие для теста. Теперь пекарней управляет мышь, а над дверью вывеска: «{#1}»."),
                Story("ru-fairy-02", Lang.Ru, StoryTheme.Fairy,
                    "Ленивый рыцарь",
                    "{@1} правит маленьким королевством и нанимает рыцаря против дракона, но рыцарь страшно ленив, и даже прозвище у него — «{прилагательное}». Рыцарь согласен, но сначала — поспать, а постель у него одна: {предмет#1}. В полдень прилетает дракон, видит спящего рыцаря и вежливо ждёт, а с собой у него — {еда}. К вечеру дракону скучно, и он ложится рядом с рыцарем. {@1} находит обоих храпящими и объявляет мир, а мирный договор называется «{любое слово}». Теперь каждый вторник — День сна, а дракон охраняет постель — {#1} — от одного зверя: {животное}."),
                Story("ru-fairy-03", Lang.Ru, StoryTheme.Fairy,
                    "Вежливая мебель",
                    "Заклинание волшебника превращает всю деревню в очень вежливую мебель. {@1} просыпается стулом, а {@2} — вот чем: {предмет}. Каждый стул, на который садятся, говорит: «{любое слово#1}», и никто не может отдохнуть. {@1} прыгает к волшебнику жаловаться, а тот ужинает — на тарелке {еда} — за столом, который отказывается быть столом. Стол переворачивается, волшебник падает в лужу и кричит: «{прилагательное}!» Он признаётся: это месть за то, что лет {число} все клали ноги на диван. Заклинание снимают, но каждый стул всё ещё говорит «{#1}», особенно тот, что похож вот на кого: {животное}."),
                Story("ru-fairy-04", Lang.Ru, StoryTheme.Fairy,
                    "Голосуй за лягушку",
                    "Говорящая лягушка идёт в мэры, и {@1} руководит её кампанией. Лягушка обещает каждому бесплатно одно: {еда#1}, и пруд {где? например: в бане}. На дебатах лягушка только квакает, и {@1} переводит: «{любое слово}». Соперник — {животное} — требует доказать, что лягушка умеет читать. {@1} даёт лягушке то, что под рукой: {предмет}, и лягушка читает вверх ногами. Лягушка всё равно побеждает, и первый закон гласит: каждый вторник — день под названием «{#1}», а музыка в этот день — «{прилагательное}»."),
                Story("ru-fairy-05", Lang.Ru, StoryTheme.Fairy,
                    "Три точных желания",
                    "{@1} находит лампу, и джинн предлагает три желания, но понимает всё буквально. {@1} просит богатства, и джинн приводит зверя по имени Богатство — это {животное#1}. Потом {@1} хочет дом у моря, и джинн переносит море {куда? например: на Луну}. Для последнего желания {@1} пишет письмо на двенадцать страниц, и стиль у письма — «{прилагательное}». Джинн читает, говорит: «{любое слово}» — и {@1} становится вот чем: {предмет}. Теперь {@1} стоит на полке у джинна, а {#1} каждое утро вытирает пыль, и вместо тряпки — {еда}."),
                Story("ru-misc-01", Lang.Ru, StoryTheme.Misc,
                    "Долма из космоса",
                    "Во дворе садится космический корабль, и пришельцам нужно одно: научиться делать долму. {@1} начинает урок, но вместо виноградных листьев пришельцы привезли вот что: {предмет#1}. Они заворачивают мясо в то, что привезли, — {#1}, — и кухню заполняет дым. {@2} бежит за соседкой, и та приходит с опытом лет {число} и питомцем — {животное}. Оказывается, соседка тоже пришелец: прилетела на урок долмы и осталась. Пришельцы добавляют в рецепт секретный ингредиент — {еда} — и улетают довольные. Теперь на их планете каждый год фестиваль долмы в кратере «{любое слово}», и {@1} — почётный гость."),
                Story("ru-misc-02", Lang.Ru, StoryTheme.Misc,
                    "Герой носков",
                    "{@1} — супергерой, и единственная суперсила — находить потерянные носки. Город ничего не платит, только по вторникам выдаёт одно: {еда}. Однажды звонит мэр: пропал левый носок, а до речи мэра — минут {число}. {@1} находит его за одиннадцать секунд: он {где? например: в бане}, внутри вещи под названием {предмет}. Мэр отказывается его надевать: носок пахнет, как {животное}, и {@1} брызгает на него духами «{прилагательное}». Духи такие сильные, что все потерянные носки города сбегаются на запах. Теперь {@1} хранит девять тысяч носков без единой пары, а газеты называют это «{любое слово}»."),
                Story("ru-misc-03", Lang.Ru, StoryTheme.Misc,
                    "Вчерашний лифт",
                    "Лифт в доме, где живёт {@1}, застревает между двумя часовыми поясами. За левой дверью — утро понедельника, а за правой — вечеринка прошлой субботы, и на столе {еда}. {@1} шагает на вечеринку, и всё «{прилагательное}», пока не звонит начальник насчёт отчёта. Мастер приходит из следующего вторника, а с ним — {животное#1} и инструмент: {предмет}. Он жмёт одну кнопку, и теперь лифт открывается только {где? например: в бане}, причём на день раньше. {@1} всё равно ездит на нём и больше никогда не опаздывает, потому что приезжает вчера, а рядом — {#1}."),
                Story("ru-misc-04", Lang.Ru, StoryTheme.Misc,
                    "Статуя жалуется",
                    "Ночью статуя в музее оживает и пишет жалобу на посетителей. Они показывают пальцем, трогают, а один назвал её нос «{прилагательное}». {@1} работает ночным охранником и пытается успокоить её чаем, а к чаю — {еда}. Статуя требует переехать {куда? например: на Луну}, где на неё никто не будет смотреть. {@1} перевозит её, и к утру посмотреть на неё стоят в очереди человек {число}. Теперь статуя продаёт билеты и сувенир со своим лицом: {предмет}. Она зарабатывает больше музея, а {@1} охраняет её с табличкой: «{любое слово}»."),
                Story("ru-misc-05", Lang.Ru, StoryTheme.Misc,
                    "Мяч уходит на пенсию",
                    "В середине финала мяч объявляет, что уходит на пенсию. Он катится к скамейке, надевает вещь под названием {предмет#1} и просит чаю, а к чаю — {еда}. {@1}, капитан, пытается играть без мяча, и мячом становится {животное}, но судья говорит, что это нарушает правило «{любое слово}». Тогда {@1} предлагает мячу контракт «{прилагательное}» и отпуск {где? например: в бане}. Мяч соглашается сыграть последнюю минуту и нарочно забивает в свои ворота. Теперь мяч тренирует соперников и на каждом матче носит одну вещь: {#1}."),
            ],
        };
    }
}
